import React from 'react';

const Skills = () => {
  const skills = ["React", "React Native", "JavaScript", "Swift", "Kotlin", "Firebase", "HTML", "CSS", "PostgreSQL"];

  return (
    <section id="skills" style={{ padding: '50px 20px', background: '#f5f5f5' }}>
      <h2>Skills</h2>
      <ul style={{ listStyle: 'none', display: 'flex', flexWrap: 'wrap', gap: '15px', padding: 0 }}>
        {skills.map(skill => (
          <li key={skill} style={{ padding: '10px 15px', background: '#ddd', borderRadius: '5px' }}>{skill}</li>
        ))}
      </ul>
    </section>
  );
};

export default Skills;
